public enum SyncWatchLayouts {
    public static let sourceDigest = "6290c6f16c4fcde482b14b4d805ddbdfb4e80f6ed8a1d307990ea8f60551fc22"
    public static let coordinateSize = 20.0
    public static func themeColor(_ role: String, theme: SyncWatchTheme) -> Color? {
        switch role {
        case "background": theme.background
        case "backgroundDeep": theme.backgroundDeep
        case "border": theme.border
        case "gradientStart": theme.gradientStart
        case "surface": theme.surface
        case "surfaceRaised": theme.surfaceRaised
        case "text": theme.text
        case "accent": theme.accent
        case "accentSoft": theme.accentSoft
        case "success": theme.success
        case "textSecondary": theme.textSecondary
        case "inputFill": theme.inputFill
        case "selection": theme.selection
        default: nil
